import json, re
p='/mnt/data/LSF/baseline_results/court/agentic_codex_qa_gpt54_all/first_10_queries/q01/logs/q01.manifest.json'
obj=json.load(open(p))
num_re=re.compile(r'\\b\\d{2,}-\\d{2,6}\\b')
stop_block_prefixes=('D.C. No','D.C. Nos','Agency No','Agency Nos','BAP No','BAP Nos','NLRB No','NLRB Nos','Tax Ct. No','Tax Ct. Nos')
results=[]
for d in obj['documents']:
    lines=open(d['doc_path'],'r',errors='ignore').read().replace('\\f','\\n').splitlines()
    nums=[]
    for i,line in enumerate(lines[:220]):
        s=line.strip()
        if not (s.startswith('No.') or s.startswith('Nos.')):
            continue
        block=[s]
        for nxt in lines[i+1:i+7]:
            t=nxt.strip()
            if not t:
                block.append(t)
                continue
            if t.startswith(stop_block_prefixes):
                break
            if t.startswith('No.') or t.startswith('Nos.'):
                break
            if t in ('OPINION','ORDER') or t.startswith('Appeal from') or t.startswith('Before:') or t.startswith('BEFORE:'):
                break
            block.append(t)
        joined=' '.join(block)
        for n in num_re.findall(joined):
            if n not in nums:
                nums.append(n)
    results.append((d['doc_name'], nums))
for name, nums in results:
    print(name+'\\t'+(', '.join(nums) if nums else 'NO_MATCH'))
print('NO_MATCHES', sum(1 for _,n in results if not n))
